import{_ as a,o as i,c as e,aw as o}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"API","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/api/api.md","filePath":"wiki/dev-commit/network/network/api/api.md"}'),l={name:"wiki/dev-commit/network/network/api/api.md"};function r(s,t,n,c,p,d){return i(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>API</strong> (Application Programming Interface, программный интерфейс приложения) - описание способов (набор классов, процедур, функций, структур или констант), которыми одна компьютерная программа может взаимодействовать с другой программой</li></ul></div><ul><li>API определяет функциональность, которую предоставляет программа (модуль, библиотека), при этом API позволяет абстрагироваться от того, как именно эта функциональность реализована</li><li>Программные компоненты взаимодействуют друг с другом посредством API. При этом обычно компоненты образуют иерархию — высокоуровневые компоненты используют API низкоуровневых компонентов, а те, в свою очередь, используют API ещё более низкоуровневых компонентов</li></ul><h2 id="сигнатуры-и-семантика" tabindex="-1">Сигнатуры и семантика <a class="header-anchor" href="#сигнатуры-и-семантика" aria-label="Permalink to &quot;Сигнатуры и семантика&quot;">​</a></h2><blockquote><p>API библиотеки функций и классов включает в себя описание сигнатур функций и семантики функций</p></blockquote><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Сигнатура функции</strong> - часть общего объявления функции, позволяющая средствам трансляции идентифицировать функцию среди других</li><li><strong>Семантика функции</strong> - описание того, что данная функция делает. Семантика функции включает в себя описание того, что является результатом вычисления функции, как и от чего этот результат зависит</li></ul></div>',7)])])}const _=a(l,[["render",r]]);export{u as __pageData,_ as default};
